    83	class RateLimiter {
    84	  private minIntervalMs: number;
    85	  private last = 0;
    86	  constructor(perMin: number) {
    87	    this.minIntervalMs = 60_000 / perMin;
    88	  }
    89	  async wait() {
    90	    const elapsed = Date.now() - this.last;
    91	    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    92	    this.last = Date.now();
    93	  }
    94	}
