    96	async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
    97	  await limiter.wait();
    98	  const headers: Record<string, string> = { "User-Agent": UA };
    99	  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;
   100	  const res = await fetch(url, { headers });
   101	  if (res.status === 429 && attempt <= 6) {
   102	    const retryAfterMs = Number(res.headers.get("retry-after") ?? 0) * 1000;
   103	    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
   104	    console.warn(`  [rate-limit] 429 — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
   105	    await new Promise((r) => setTimeout(r, backoffMs));
   106	    return apiFetch(limiter, url, attempt + 1);
   107	  }
   108	  if (res.status >= 500 && attempt <= 4) {
   109	    const backoffMs = 1000 * 2 ** attempt;
   110	    console.warn(`  [server-error] ${res.status} — retrying in ${Math.round(backoffMs / 1000)}s`);
   111	    await new Promise((r) => setTimeout(r, backoffMs));
   112	    return apiFetch(limiter, url, attempt + 1);
   113	  }
   114	  return res;
   115	}
