async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
  await limiter.wait();
  const res = await fetch(url, { headers: { "User-Agent": "Nxeon/1.0 (mods@nxeon.cloud)" } });
  if ((res.status === 429 || res.status >= 500) && attempt <= 5) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [retry] HTTP ${res.status} on ${url.replace(STEAM_KEY, "***")} — backing off ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  return res;
}

// ── Steam types (only the fields we read) ────────────────────────────────
type PublishedFile = {
  result: number;
  publishedfileid: string;
  creator?: string;
  title?: string;
  short_description?: string;
  preview_url?: string;
  subscriptions?: number;
  banned?: boolean;
  visibility?: number;
  time_updated?: number;
};
type QueryFilesResponse = { response: { total?: number; publishedfileditails?: never; publishedfiledetails?: PublishedFile[] } };
type PlayerSummary = { steamid: string; personaname?: string; avatarfull?: string };

function kebab(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60) || "workshop-item";
}

type Counters = { seen: number; qualified: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  return { seen: 0, qualified: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
}

async function fetchAuthors(limiter: RateLimiter, steamIds: string[]): Promise<Map<string, PlayerSummary>> {
  const out = new Map<string, PlayerSummary>();
  const unique = [...new Set(steamIds.filter(Boolean))];
  for (let i = 0; i < unique.length; i += 100) {
    const slice = unique.slice(i, i + 100);
    const url = `${API}/ISteamUser/GetPlayerSummaries/v2/?key=${STEAM_KEY}&steamids=${slice.join(",")}`;
    const res = await apiFetch(limiter, url);
    if (!res.ok) continue;
    const body = (await res.json()) as { response?: { players?: PlayerSummary[] } };
    for (const p of body.response?.players ?? []) out.set(p.steamid, p);
  }
  return out;
}

async function importFamily(opts: {
  family: string;
  appid: number;
  limiter: RateLimiter;
  apply: boolean;
  minSubscriptions: number;
  maxPerFamily: number;
  maxPages?: number;
}): Promise<Counters> {
  const { family, appid, limiter, apply, minSubscriptions, maxPerFamily, maxPages } = opts;
  const counters = emptyCounters();
  let cursor = "*";
  let page = 0;
  let total: number | undefined;
  const qualifiedBatch: PublishedFile[] = [];

  for (;;) {
    if (maxPages !== undefined && page >= maxPages) break;
    if (counters.qualified >= maxPerFamily) break;

    const url =
      `${API}/IPublishedFileService/QueryFiles/v1/` +
      `?key=${STEAM_KEY}&appid=${appid}&numperpage=${PAGE_SIZE}&cursor=${encodeURIComponent(cursor)}` +
      `&query_type=${RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS}&return_short_description=true&format=json`;
    const res = await apiFetch(limiter, url);
    page++;
    if (!res.ok) {
      console.error(`  [${family}] HTTP ${res.status} at page ${page} — stopping this family early`);
      break;
    }
    const body = (await res.json()) as QueryFilesResponse & { response: { next_cursor?: string } };
    const items = body.response.publishedfiledetails ?? [];
    total = body.response.total ?? total;
    counters.seen += items.length;
    if (items.length === 0) break;

    let sawBelowFloor = false;
    for (const item of items) {
      if (item.result !== 1 || item.banned || (item.visibility ?? 0) !== 0) continue;
      const subs = item.subscriptions ?? 0;
      if (subs < minSubscriptions) {
        sawBelowFloor = true;
        break; // sorted descending by subscriptions — nothing after this qualifies either
      }
      if (!item.title || !item.publishedfileid) continue;
      qualifiedBatch.push(item);
      counters.qualified++;
      if (counters.qualified >= maxPerFamily) break;
    }

    const nextCursor = (body.response as { next_cursor?: string }).next_cursor;
    console.log(
      `  [${family}] page=${page} fetched=${items.length} qualified_running=${counters.qualified} total=${total ?? "?"}`
    );
    if (sawBelowFloor || !nextCursor || nextCursor === cursor) break;
    cursor = nextCursor;
  }

  if (qualifiedBatch.length === 0) {
    console.log(`  [${family}] nothing qualified (floor=${minSubscriptions} subscribers)`);
    return counters;
  }

  if (!apply) {
    counters.upserted = qualifiedBatch.length;
    return counters;
  }

  const authors = await fetchAuthors(limiter, qualifiedBatch.map((i) => i.creator ?? ""));
