/**
 * Backfill `GameMod.upstreamUpdatedAt` — the REAL last-modified timestamp on
 * each mod's own upstream source, for the NxLabs "Recently Updated" rail.
 *
 * WHY THIS EXISTS. The owner asked for a "Recently Updated" row and, in the
 * same breath, whether mods "have recent updates" tracked at all. They
 * don't: `GameMod.updatedAt` is Prisma's `@updatedAt` auto-field — it moves
 * whenever OUR db row is touched (a bulk re-import, a verify pass), which is
 * completely unrelated to when the mod's real author last shipped anything.
 * Building "Recently Updated" off that field would show whatever we happened
 * to last re-sync, not what's actually fresh — dishonest, and the opposite
 * of this catalogue's whole "real numbers, never guesses" convention (see
 * lib/mods-catalog.ts's own header). `upstreamUpdatedAt` is the honest fix:
 * a real timestamp read straight from each source's own API, confirmed live
 * against that API by this script's author before being trusted (see the
 * per-source notes below — one of the task's own assumed field names,
 * Modrinth's `date_modified`, turned out not to exist; the real field is
 * `updated`).
 *
 * PER-SOURCE FIELD, CONFIRMED LIVE 2026-09-20 (not assumed from docs):
 *
 *   - Modrinth (32,243 rows, 99.7% of catalogue's mod_io+everything-else):
 *     the bulk `GET /v2/projects?ids=[...]` response's real `updated` field
 *     (ISO 8601). `date_modified` — this task's own first guess — does NOT
 *     exist on the live API; confirmed via `GET /v2/project/sodium`, which
 *     returns `updated`/`published`, nothing named `date_modified`. Same
 *     bulk endpoint + batch size + rate limit as
 *     scripts/backfill-modrinth-descriptions.ts, whose own investigation
 *     this mirrors.
 *
 *   - GitHub (24 rows): `GET /repos/{full_name}`'s real `pushed_at` — the
 *     same field scripts/import-github-catalog.ts already reads to compute
 *     staleness/upstreamOk, confirmed live again here
 *     (danielkrupinski/Osiris → real pushed_at). Not `published_at` off a
 *     release: these CS2 plugins are installed by fetching repo state at
 *     install time (worker/game-mods.ts's resolveUrl(), not a pinned
 *     release asset stored here), so the repo's own last-push is the
 *     meaningful "did this ship anything new" signal, and every row already
 *     has a real GitHub `full_name` in `sourceId` — no extra API shape to
 *     learn.
 *
 *   - Thunderstore (1,776 rows): NOT a per-package fetch. The real field
 *     lives on `versions[]` in the SAME bulk-per-community v1 catalogue
 *     endpoint scripts/import-thunderstore-catalog.ts already fetches whole
 *     (`https://thunderstore.io/c/{community}/api/v1/package/`, one GET
 *     returns EVERY package in that community) — each version object has a
 *     real `date_created`, and the latest version's `date_created` (same
 *     `latestVersion()` selection that script already uses) is the mod's
 *     real last-shipped timestamp. No separate top-level "date_updated" on
 *     this particular (v1, non-experimental) response shape. Only 4
 *     requests total cover all 1,776 rows.
 *
 *   - Steam Workshop (8,950 rows): `GetPublishedFileDetails`'s real
 *     `time_updated` (Unix seconds) — confirmed live against 3 real rows
 *     already in this DB (Squad AdminTools, SuperMod, Steel Division), all
 *     returned a real, distinct `time_updated` newer than `time_created`.
 *     Matches this task's own assumption exactly. Batched via the same POST
 *     form (`publishedfileids[N]=`) at up to 100 ids/call.
 *
 *   - mod.io (2,725 rows — real, already-imported data even though
 *     scripts/import-modio-catalog.ts and this schema comment line are still
 *     uncommitted as of this script's writing; see git log). Real
 *     `date_updated` (Unix seconds) on both the single-mod
 *     `GET /games/{gameId}/mods/{modId}` endpoint and the list endpoint —
 *     confirmed live on Core Keeper's "Better Minimap" and "CoreLib". Fetched
 *     per-mod (id + its family's mod.io gameId, from the same GAME_ID map
 *     import-modio-catalog.ts uses) since sourceId alone isn't enough to
 *     build the URL — mod.io's REST path is scoped by game.
 *
 *   - uMod / SpigotMC / Nexus / Codefling (29 + 6 + 12 + 1 = 48 rows): not
 *     touched by this pass. Same call as
 *     scripts/backfill-modrinth-descriptions.ts made for the same reason —
 *     48 rows across four different APIs this session hasn't investigated is
 *     not where a backfill moves the needle, and this script would rather
 *     leave them honestly null than guess a field name un-verified.
 *
 * IDEMPOTENT: only touches rows where `upstreamUpdatedAt IS NULL` by
 * default (re-running converges instead of re-fetching forever); pass
 * --refresh to also re-check rows that already have a value (a mod can ship
 * a real new update after this first pass).
 *
 * SAFETY: dry run by default. Writing goes through the same
 * scripts/db-target-guard.ts NXEON_DB_TARGET confirmation as every other
 * writing script in this repo.
 *
 *   Dry run, tiny slice of one source:
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/backfill-upstream-updated.ts --source=modrinth --limit=50
 *
 *   Real write, one source:
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/backfill-upstream-updated.ts --source=modrinth --apply
 *
 *   Full real run (all 5 wired sources):
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/backfill-upstream-updated.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("backfill-upstream-updated.ts");

import { db } from "../lib/db";

const UA = "Nxeon/1.0 (mods@nxeon.cloud)";

function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  const sourceArg = get("source");
  return {
    apply: argv.includes("--apply"),
    refresh: argv.includes("--refresh"),
    limit: get("limit") ? Number(get("limit")) : undefined,
    sources: sourceArg ? sourceArg.split(",") : undefined,
  };
}

class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const elapsed = Date.now() - this.last;
    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    this.last = Date.now();
  }
}

async function fetchWithRetry(limiter: RateLimiter, url: string, init: RequestInit = {}, attempt = 1): Promise<Response> {
  await limiter.wait();
  const res = await fetch(url, init);
  if (res.status === 429 && attempt <= 6) {
    const retryAfterMs = Number(res.headers.get("retry-after") ?? 0) * 1000;
    const backoffMs = Math.max(retryAfterMs, 1000 * 2 ** attempt);
    console.warn(`  [rate-limit] 429 on ${url.split("?")[0]} — backing off ${Math.round(backoffMs / 1000)}s (attempt ${attempt})`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return fetchWithRetry(limiter, url, init, attempt + 1);
  }
  if (res.status >= 500 && attempt <= 4) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [server-error] ${res.status} on ${url.split("?")[0]} — retrying in ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return fetchWithRetry(limiter, url, init, attempt + 1);
  }
  return res;
}

type Row = { id: string; sourceId: string | null; name: string; gameFamily: string };

type SourceResult = { checked: number; filled: number; unchanged: number; missing: number; failed: number };
function emptyResult(): SourceResult {
  return { checked: 0, filled: 0, unchanged: 0, missing: 0, failed: 0 };
}

async function applyUpdate(row: Row, date: Date | null, apply: boolean, result: SourceResult) {
  result.checked++;
  if (!date || Number.isNaN(date.getTime())) {
    result.missing++;
    return;
  }
  result.filled++;
  if (!apply) return;
  try {
    await db.gameMod.update({ where: { id: row.id }, data: { upstreamUpdatedAt: date } });
  } catch (e) {
    result.filled--;
    result.failed++;
    console.error(`  [db] failed to update ${row.name} (${row.id}): ${e instanceof Error ? e.message : e}`);
  }
}

async function loadRows(source: string, refresh: boolean, limit: number | undefined): Promise<Row[]> {
  return db.gameMod.findMany({
    where: {
      source,
      sourceId: { not: null },
      ...(refresh ? {} : { upstreamUpdatedAt: null }),
    },
    select: { id: true, sourceId: true, name: true, gameFamily: true },
    ...(limit ? { take: limit } : {}),
  });
}

// ── Modrinth ─────────────────────────────────────────────────────────────
async function backfillModrinth(opts: { refresh: boolean; limit?: number; apply: boolean }): Promise<SourceResult> {
  const result = emptyResult();
  const rows = await loadRows("modrinth", opts.refresh, opts.limit);
  console.log(`[modrinth] ${rows.length} row(s) to check`);
  if (rows.length === 0) return result;

  const BATCH_SIZE = 100; // Modrinth's real cap on /projects?ids=[...]
  const limiter = new RateLimiter(280); // stay under Modrinth's real 300/min
  const MODRINTH_KEY = process.env.MODRINTH_API_KEY ?? "";
  const headers: Record<string, string> = { "User-Agent": UA };
  if (MODRINTH_KEY) headers.Authorization = MODRINTH_KEY;

  const bySlug = new Map(rows.map((r) => [r.sourceId!, r]));
  const slugs = [...bySlug.keys()];

  for (let i = 0; i < slugs.length; i += BATCH_SIZE) {
    const batch = slugs.slice(i, i + BATCH_SIZE);
    const idsParam = encodeURIComponent(JSON.stringify(batch));
    const res = await fetchWithRetry(limiter, `https://api.modrinth.com/v2/projects?ids=${idsParam}`, { headers });
    if (!res.ok) {
      console.error(`  [batch ${i / BATCH_SIZE + 1}] HTTP ${res.status} — skipping ${batch.length} row(s)`);
      result.failed += batch.length;
      continue;
    }
    const projects: Array<{ id: string; slug: string; updated?: string }> = await res.json();
    const byIdOrSlug = new Map<string, { updated?: string }>();
    for (const p of projects) {
      byIdOrSlug.set(p.id, p);
      byIdOrSlug.set(p.slug, p);
    }
    for (const requestedSlug of batch) {
      const row = bySlug.get(requestedSlug)!;
      const proj = byIdOrSlug.get(requestedSlug);
      if (!proj) {
        result.checked++;
        result.missing++;
        continue;
      }
      await applyUpdate(row, proj.updated ? new Date(proj.updated) : null, opts.apply, result);
    }
    console.log(
      `  [batch ${Math.floor(i / BATCH_SIZE) + 1}/${Math.ceil(slugs.length / BATCH_SIZE)}] ` +
        `checked=${result.checked} filled=${result.filled} missing=${result.missing} failed=${result.failed}`
    );
  }
  return result;
}

// ── GitHub ───────────────────────────────────────────────────────────────
async function backfillGithub(opts: { refresh: boolean; limit?: number; apply: boolean }): Promise<SourceResult> {
  const result = emptyResult();
  const rows = await loadRows("github", opts.refresh, opts.limit);
  console.log(`[github] ${rows.length} row(s) to check`);
  if (rows.length === 0) return result;

  const GITHUB_TOKEN = process.env.GITHUB_TOKEN ?? "";
  // Unauthenticated: 60 req/hr core (confirmed live, same as
  // scripts/import-github-catalog.ts). This catalogue has 24 github rows
  // total, so a gentle self-pace (well inside the hourly cap either way)
  // is enough — no need to spread across a full hour.
  const limiter = new RateLimiter(GITHUB_TOKEN ? 300 : 50);
  const headers: Record<string, string> = { "User-Agent": UA, Accept: "application/vnd.github+json" };
  if (GITHUB_TOKEN) headers.Authorization = `Bearer ${GITHUB_TOKEN}`;

  for (const row of rows) {
    const res = await fetchWithRetry(limiter, `https://api.github.com/repos/${row.sourceId}`, { headers });
    if (res.status === 404) {
      result.checked++;
      result.missing++;
      continue;
    }
    if (!res.ok) {
      result.checked++;
      result.failed++;
      console.error(`  [github] ${row.sourceId} → HTTP ${res.status}`);
      continue;
    }
    const repo: { pushed_at?: string } = await res.json();
    await applyUpdate(row, repo.pushed_at ? new Date(repo.pushed_at) : null, opts.apply, result);
  }
  console.log(`  checked=${result.checked} filled=${result.filled} missing=${result.missing} failed=${result.failed}`);
  return result;
}

// ── Thunderstore ─────────────────────────────────────────────────────────
const THUNDERSTORE_COMMUNITIES = ["valheim", "sons-of-the-forest", "schedule-i", "sunkenland"];

type TsVersion = { date_created?: string };
type TsPackage = { full_name: string; versions?: TsVersion[] };

function latestVersionDate(pkg: TsPackage): Date | null {
  const vs = pkg.versions ?? [];
  if (vs.length === 0) return null;
  const latest = vs.reduce((a, b) => (new Date(b.date_created ?? 0) > new Date(a.date_created ?? 0) ? b : a));
  return latest.date_created ? new Date(latest.date_created) : null;
}

async function backfillThunderstore(opts: { refresh: boolean; limit?: number; apply: boolean }): Promise<SourceResult> {
  const result = emptyResult();
  const rows = await loadRows("thunderstore", opts.refresh, opts.limit);
  console.log(`[thunderstore] ${rows.length} row(s) to check`);
  if (rows.length === 0) return result;

  const bySourceId = new Map(rows.map((r) => [r.sourceId!, r]));
  const limiter = new RateLimiter(30); // undocumented rate limit — self-pace politely, only 4 requests needed total

  const byFullName = new Map<string, TsPackage>();
  for (const community of THUNDERSTORE_COMMUNITIES) {
    const res = await fetchWithRetry(limiter, `https://thunderstore.io/c/${community}/api/v1/package/`, {
      headers: { "User-Agent": UA },
    });
    if (!res.ok) {
      console.error(`  [${community}] HTTP ${res.status} — skipping this community's package list`);
      continue;
    }
    const pkgs: TsPackage[] = await res.json();
    for (const p of pkgs) byFullName.set(p.full_name, p);
    console.log(`  [${community}] fetched ${pkgs.length} package(s)`);
  }

  for (const [sourceId, row] of bySourceId) {
    const pkg = byFullName.get(sourceId);
    if (!pkg) {
      result.checked++;
      result.missing++;
      continue;
    }
    await applyUpdate(row, latestVersionDate(pkg), opts.apply, result);
  }
  console.log(`  checked=${result.checked} filled=${result.filled} missing=${result.missing} failed=${result.failed}`);
  return result;
}

// ── Steam Workshop ───────────────────────────────────────────────────────
async function backfillSteamWorkshop(opts: { refresh: boolean; limit?: number; apply: boolean }): Promise<SourceResult> {
  const result = emptyResult();
  const rows = await loadRows("steam_workshop", opts.refresh, opts.limit);
  console.log(`[steam_workshop] ${rows.length} row(s) to check`);
  if (rows.length === 0) return result;

  const STEAM_KEY = process.env.STEAM_WEB_API_KEY ?? "";
  if (!STEAM_KEY) {
    console.error("  [steam_workshop] STEAM_WEB_API_KEY is not set — skipping this source entirely");
    result.checked = rows.length;
    result.failed = rows.length;
    return result;
  }
  const limiter = new RateLimiter(30);
  const BATCH_SIZE = 100;
  const bySourceId = new Map(rows.map((r) => [r.sourceId!, r]));
  const ids = [...bySourceId.keys()];

  for (let i = 0; i < ids.length; i += BATCH_SIZE) {
    const batch = ids.slice(i, i + BATCH_SIZE);
    const form = new URLSearchParams({ itemcount: String(batch.length), key: STEAM_KEY });
    batch.forEach((id, idx) => form.set(`publishedfileids[${idx}]`, id));
    const res = await fetchWithRetry(
      limiter,
      "https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/",
      { method: "POST", body: form }
    );
    if (!res.ok) {
      console.error(`  [batch ${i / BATCH_SIZE + 1}] HTTP ${res.status} — skipping ${batch.length} row(s)`);
      result.failed += batch.length;
      continue;
    }
    const body: { response?: { publishedfiledetails?: Array<{ publishedfileid: string; result: number; time_updated?: number }> } } =
      await res.json();
    const details = body.response?.publishedfiledetails ?? [];
    const byId = new Map(details.map((d) => [d.publishedfileid, d]));
    for (const id of batch) {
      const row = bySourceId.get(id)!;
      const detail = byId.get(id);
      if (!detail || detail.result !== 1) {
        result.checked++;
        result.missing++;
        continue;
      }
      await applyUpdate(row, detail.time_updated ? new Date(detail.time_updated * 1000) : null, opts.apply, result);
    }
    console.log(
      `  [batch ${Math.floor(i / BATCH_SIZE) + 1}/${Math.ceil(ids.length / BATCH_SIZE)}] ` +
        `checked=${result.checked} filled=${result.filled} missing=${result.missing} failed=${result.failed}`
    );
  }
  return result;
}

// ── mod.io ───────────────────────────────────────────────────────────────
// Same family→gameId map as scripts/import-modio-catalog.ts (kept as a
// separate literal rather than importing from that in-progress/uncommitted
// script, per this task's "don't edit the in-progress pipeline" constraint).
const MODIO_GAME_ID: Record<string, number> = {
  corekeeper: 5289,
  spaceengineers: 264,
  sandstorm: 254,
  mordhau: 169,
};

async function backfillModio(opts: { refresh: boolean; limit?: number; apply: boolean }): Promise<SourceResult> {
  const result = emptyResult();
  const rows = await loadRows("mod_io", opts.refresh, opts.limit);
  console.log(`[mod_io] ${rows.length} row(s) to check`);
  if (rows.length === 0) return result;

  const MODIO_KEY = process.env.MODIO_API_KEY ?? "";
  if (!MODIO_KEY) {
    console.error("  [mod_io] MODIO_API_KEY is not set — skipping this source entirely");
    result.checked = rows.length;
    result.failed = rows.length;
    return result;
  }
  const limiter = new RateLimiter(55); // documented ceiling for this user-linked key is 60/min

  for (const row of rows) {
    const gameId = MODIO_GAME_ID[row.gameFamily];
    if (!gameId) {
      result.checked++;
      result.missing++;
      continue;
    }
    const res = await fetchWithRetry(
      limiter,
      `https://api.mod.io/v1/games/${gameId}/mods/${row.sourceId}?api_key=${MODIO_KEY}`,
      { headers: { "User-Agent": UA } }
    );
    if (!res.ok) {
      result.checked++;
      if (res.status === 404) result.missing++;
      else result.failed++;
      continue;
    }
    const mod: { date_updated?: number } = await res.json();
    await applyUpdate(row, mod.date_updated ? new Date(mod.date_updated * 1000) : null, opts.apply, result);
    if (result.checked % 200 === 0) {
      console.log(`  ...checked=${result.checked}/${rows.length} filled=${result.filled} missing=${result.missing} failed=${result.failed}`);
    }
  }
  console.log(`  checked=${result.checked} filled=${result.filled} missing=${result.missing} failed=${result.failed}`);
  return result;
}

const BACKFILLERS: Record<string, (opts: { refresh: boolean; limit?: number; apply: boolean }) => Promise<SourceResult>> = {
  modrinth: backfillModrinth,
  github: backfillGithub,
  thunderstore: backfillThunderstore,
  steam_workshop: backfillSteamWorkshop,
  mod_io: backfillModio,
};

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const sources = (args.sources ?? Object.keys(BACKFILLERS)).filter((s) => {
    if (!BACKFILLERS[s]) {
      console.error(`Unknown --source "${s}" — must be one of: ${Object.keys(BACKFILLERS).join(", ")}`);
      return false;
    }
    return true;
  });

  console.log(
    `[backfill-upstream-updated] sources=${sources.join(",")} ` +
      (args.refresh ? "(--refresh: including rows that already have a value) " : "(rows with upstreamUpdatedAt IS NULL) ") +
      (args.apply ? "— APPLY mode" : "— DRY RUN, no writes") +
      (args.limit ? ` limit=${args.limit}` : "")
  );

  const totals: Record<string, SourceResult> = {};
  for (const source of sources) {
    totals[source] = await BACKFILLERS[source]({ refresh: args.refresh, limit: args.limit, apply: args.apply });
  }

  console.log("\n[backfill-upstream-updated] summary:");
  for (const [source, r] of Object.entries(totals)) {
    console.log(
      `  ${source.padEnd(14)} checked=${String(r.checked).padStart(6)} ${args.apply ? "filled" : "would_fill"}=${String(r.filled).padStart(6)} missing=${String(r.missing).padStart(5)} failed=${r.failed}`
    );
  }
  if (!args.apply) console.log("\nDry run only — re-run with --apply to write.");

  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

