/**
 * Group rows by their real upstream `sourceId` — NOT a 1:1 dedup map. A
 * generic Thunderstore tool like r2modman (or, in principle, any source's
 * id) can legitimately back MULTIPLE distinct `GameMod` rows (one per
 * gameFamily it's catalogued under). Confirmed live 2026-09-20: an earlier
 * version of this script built a `Map<sourceId, Row>` here, which silently
 * collapsed those duplicates down to whichever row happened to be inserted
 * last — the other rows sharing that sourceId were never checked, filled, OR
 * counted as missing/failed; they just vanished from the run with no error.
 * Every caller below fetches upstream data ONCE per unique sourceId but
 * applies the result to every row in that sourceId's group.
 */
function groupBySourceId(rows: Row[]): Map<string, Row[]> {
  const groups = new Map<string, Row[]>();
  for (const row of rows) {
    const key = row.sourceId!;
    const group = groups.get(key);
    if (group) group.push(row);
    else groups.set(key, [row]);
  }
  return groups;
}

async function applyUpdateToGroup(rows: Row[], date: Date | null, apply: boolean, result: SourceResult) {
  for (const row of rows) await applyUpdate(row, date, apply, result);
}

