const limiter = new RateLimiter(30);
const BATCH_SIZE = 100;
const groups = groupBySourceId(rows);
const ids = [...groups.keys()];

for (let i = 0; i < ids.length; i += BATCH_SIZE) {
  const batch = ids.slice(i, i + BATCH_SIZE);
  const form = new URLSearchParams({ itemcount: String(batch.length), key: STEAM_KEY });
  batch.forEach((id, idx) => form.set(`publishedfileids[${idx}]`, id));
  const res = await fetchWithRetry(
    limiter,
    "https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/",
    { method: "POST", body: form }
  );
  if (!res.ok) {
    const rowCount = batch.reduce((sum, id) => sum + groups.get(id)!.length, 0);
    console.error(`  [batch ${i / BATCH_SIZE + 1}] HTTP ${res.status} — skipping ${rowCount} row(s)`);
    result.failed += rowCount;
    continue;
  }
  const body: { response?: { publishedfiledetails?: Array<{ publishedfileid: string; result: number; time_updated?: number }> } } =
    await res.json();
  const details = body.response?.publishedfiledetails ?? [];
  const byId = new Map(details.map((d) => [d.publishedfileid, d]));
  for (const id of batch) {
    const group = groups.get(id)!;
    const detail = byId.get(id);
    if (!detail || detail.result !== 1) {
      result.checked += group.length;
      result.missing += group.length;
      continue;
    }
    await applyUpdateToGroup(group, detail.time_updated ? new Date(detail.time_updated * 1000) : null, opts.apply, result);
  }

