import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const now = Date.now();
const day = 86400000;

const sources = ["modrinth", "github", "thunderstore", "steam_workshop", "mod_io", "umod", "spigotmc", "nexus", "codefling"];

let totals = { total: 0, filled: 0, within30: 0, within90: 0, older: 0, null: 0 };
console.log("source         | total   | has-real-date | within 30d | within 90d | older than 90d | null/unknown");
for (const source of sources) {
  const rows = await db.gameMod.findMany({ where: { source }, select: { upstreamUpdatedAt: true } });
  const total = rows.length;
  let within30 = 0, within90 = 0, older = 0, nulls = 0;
  for (const r of rows) {
    if (!r.upstreamUpdatedAt) { nulls++; continue; }
    const ageMs = now - r.upstreamUpdatedAt.getTime();
    if (ageMs <= 30 * day) within30++;
    else if (ageMs <= 90 * day) within90++;
    else older++;
  }
  const filled = total - nulls;
  console.log(`${source.padEnd(15)}| ${String(total).padStart(7)} | ${String(filled).padStart(13)} | ${String(within30).padStart(10)} | ${String(within90).padStart(10)} | ${String(older).padStart(14)} | ${String(nulls).padStart(12)}`);
  totals.total += total; totals.filled += filled; totals.within30 += within30; totals.within90 += within90; totals.older += older; totals.null += nulls;
}
console.log("-".repeat(100));
console.log(`${"TOTAL".padEnd(15)}| ${String(totals.total).padStart(7)} | ${String(totals.filled).padStart(13)} | ${String(totals.within30).padStart(10)} | ${String(totals.within90).padStart(10)} | ${String(totals.older).padStart(14)} | ${String(totals.null).padStart(12)}`);

await db.$disconnect();
EOF
